{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.full_size_inv_avail as WITH wh_inv AS ( SELECT date, TRIM( UPPER( REVERSE( SUBSTRING( REVERSE(\"Item SkuCode\"), POSITION(\'-\' IN REVERSE(\"Item SkuCode\")) + 1 ) ) ) ) AS sku_group, UPPER( REVERSE( SUBSTRING( REVERSE(\"Item SkuCode\"), 1, POSITION(\'-\' IN REVERSE(\"Item SkuCode\")) - 1 ) ) ) AS raw_size, SUM(inventory) AS wh_qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE facility IN (\'SAPL-WH2\', \'SAPL-WH1\', \'SAPL-NORTH-TAURU\') GROUP BY 1, 2,3 ), wh_inv_norm AS ( SELECT date,sku_group, CASE WHEN raw_size IS NULL OR TRIM(raw_size) = \'\' THEN \'L\' WHEN raw_size = \'01M\' THEN \'M\' WHEN raw_size = \'01XL\' THEN \'XL\' WHEN raw_size = \'06XL\' THEN \'6XL\' WHEN raw_size IN (\'XS\', \'S\', \'M\', \'L\', \'XL\') THEN raw_size WHEN raw_size IN (\'XXL\', \'2XL\', \'XXU\') THEN \'2XL\' WHEN raw_size IN (\'XXXL\', \'3XL\') THEN \'3XL\' WHEN raw_size IN (\'4XL\', \'5XL\', \'6XL\', \'7XL\', \'8XL\') THEN raw_size WHEN raw_size = \'28\' THEN \'XS\' WHEN raw_size = \'30\' THEN \'S\' WHEN raw_size = \'32\' THEN \'M\' WHEN raw_size = \'34\' THEN \'L\' WHEN raw_size = \'36\' THEN \'XL\' WHEN raw_size = \'38\' THEN \'2XL\' WHEN raw_size = \'40\' THEN \'3XL\' WHEN raw_size = \'42\' THEN \'4XL\' WHEN raw_size = \'44\' THEN \'5XL\' WHEN raw_size = \'46\' THEN \'6XL\' WHEN raw_size = \'48\' THEN \'7XL\' WHEN raw_size = \'50\' THEN \'8XL\' WHEN raw_size = \'39\' THEN \'2XL\' WHEN raw_size = \'41\' THEN \'4XL\' WHEN raw_size = \'43\' THEN \'5XL\' WHEN raw_size = \'45\' THEN \'6XL\' WHEN raw_size = \'1\' THEN \'XS\' WHEN raw_size = \'2\' THEN \'S\' WHEN raw_size = \'3\' THEN \'M\' WHEN raw_size = \'4\' THEN \'L\' WHEN raw_size = \'5\' THEN \'XL\' WHEN raw_size = \'6\' THEN \'2XL\' ELSE raw_size END AS size, wh_qty FROM wh_inv ), offline_sizes AS ( SELECT date, SKU_GROUP AS sku_group, \'XS\' AS size, COALESCE(XS_UNITS, 0) AS store_qty, COALESCE(JIT_XS_UNITS, 0) AS jit_qty FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'S\', COALESCE(S_UNITS, 0), COALESCE(JIT_S_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'M\', COALESCE(M_UNITS, 0), COALESCE(JIT_M_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'L\', COALESCE(L_UNITS, 0), COALESCE(JIT_L_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'XL\', COALESCE(XL_UNITS, 0), COALESCE(JIT_XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'2XL\', COALESCE(XXL_UNITS, 0), COALESCE(JIT_2XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'3XL\', COALESCE(XL3_UNITS, 0), COALESCE(JIT_3XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'4XL\', COALESCE(XL4_UNITS, 0), COALESCE(JIT_4XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'5XL\', COALESCE(XL5_UNITS, 0), COALESCE(JIT_5XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'6XL\', COALESCE(XL6_UNITS, 0), COALESCE(JIT_6XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 ), for_variants as ( select * from ((select DISTINCT TRIM( UPPER(REGEXP_REPLACE(value:sku::STRING, \'-[^-]+$\', \'\')) ) AS sku_group, TRIM(UPPER(SPLIT_PART(value:sku::STRING, \'-\', -1))) AS raw_size, from snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(INPUT => PARSE_JSON(variants)) AS value WHERE value:sku IS NOT NULL) union all (select distinct TRIM( UPPER(REGEXP_REPLACE(sku::STRING, \'-[^-]+$\', \'\')) ) sku_group, size raw_size from snitch_db.maplemonk.uc_final_item_master)) ), variant_exists AS ( SELECT DISTINCT sku_group, raw_size, CASE WHEN Raw_size = \'01M\' THEN \'M\' WHEN Raw_size = \'01XL\' THEN \'XL\' WHEN Raw_size = \'06XL\' THEN \'6XL\' WHEN Raw_size IN (\'XS\', \'S\', \'M\', \'L\', \'XL\') THEN Raw_size WHEN Raw_size IN (\'XXL\', \'2XL\', \'XXU\') THEN \'2XL\' WHEN Raw_size IN (\'XXXL\', \'3XL\') THEN \'3XL\' WHEN Raw_size IN (\'4XL\', \'5XL\', \'6XL\', \'7XL\', \'8XL\') THEN Raw_size WHEN Raw_size = \'28\' THEN \'XS\' WHEN Raw_size = \'30\' THEN \'S\' WHEN Raw_size = \'32\' THEN \'M\' WHEN Raw_size = \'34\' THEN \'L\' WHEN Raw_size = \'36\' THEN \'XL\' WHEN Raw_size = \'38\' THEN \'2XL\' WHEN Raw_size = \'40\' THEN \'3XL\' WHEN Raw_size = \'42\' THEN \'4XL\' WHEN Raw_size = \'44\' THEN \'5XL\' WHEN Raw_size = \'46\' THEN \'6XL\' WHEN Raw_size = \'48\' THEN \'7XL\' WHEN Raw_size = \'50\' THEN \'8XL\' WHEN Raw_size = \'39\' THEN \'2XL\' WHEN Raw_size = \'41\' THEN \'4XL\' WHEN Raw_size = \'43\' THEN \'5XL\' WHEN Raw_size = \'45\' THEN \'6XL\' ELSE null END AS size FROM for_variants ), wh_by_size AS ( SELECT date, sku_group, size, SUM(wh_qty) AS wh_qty FROM wh_inv_norm GROUP BY 1, 2, 3 ), offline_by_size AS ( SELECT date, UPPER(sku_group) AS sku_group, size, SUM(store_qty) AS store_qty, SUM(jit_qty) AS jit_qty FROM offline_sizes GROUP BY 1, 2, 3 ), base AS ( SELECT COALESCE(w.date, o.date) AS date, UPPER(TRIM(COALESCE(w.sku_group, o.sku_group))) AS sku_group, mm.l1_category, mm.category, mm.meta1, mm.meta2, mm.meta3, UPPER(TRIM(COALESCE(w.size, o.size))) AS size, COALESCE(w.wh_qty, 0) AS wh_qty, COALESCE(o.store_qty, 0) AS store_qty, COALESCE(o.jit_qty, 0) AS jit_qty, COALESCE(o.store_qty, 0) + COALESCE(o.jit_qty, 0) AS store_plus_jit_qty, COALESCE(w.wh_qty, 0) + COALESCE(o.store_qty, 0) + COALESCE(o.jit_qty, 0) AS total_qty, CASE WHEN COALESCE(w.wh_qty, 0) > 0 THEN 1 ELSE 0 END AS wh_avail, CASE WHEN COALESCE(o.store_qty, 0) + COALESCE(o.jit_qty, 0) > 0 THEN 1 ELSE 0 END AS offline_avail, CASE WHEN COALESCE(w.wh_qty, 0) + COALESCE(o.store_qty, 0) + COALESCE(o.jit_qty, 0) > 0 THEN 1 ELSE 0 END AS overall_avail FROM wh_by_size w FULL OUTER JOIN offline_by_size o USING (date, sku_group, size) LEFT JOIN snitch_db.maplemonk.meta_mapping_cogs_sku mm ON UPPER(TRIM(COALESCE(w.sku_group, o.sku_group))) = UPPER(TRIM(mm.sku_group)) ), req AS ( SELECT b.*, CASE WHEN v.sku_group IS NOT NULL THEN 1 ELSE 0 END AS variant_exists, CASE WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'S\' THEN 1 ELSE 0 END AS cc, CASE WHEN v.sku_group IS NULL THEN NULL WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'XS\' THEN 10 WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'S\' THEN 30 WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'M\' THEN 40 WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'L\' THEN 40 WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'XL\' THEN 30 WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'2XL\' THEN 10 WHEN UPPER(l1_category) = \'PLUS\' AND UPPER(category) IN (\'SHIRTS\', \'TSHIRTS\') AND size IN (\'3XL\', \'4XL\', \'5XL\', \'6XL\') THEN 20 WHEN UPPER(l1_category) = \'PLUS\' AND UPPER(category) IN (\'TROUSERS\', \'JEANS\') AND size = \'3XL\' THEN 30 WHEN UPPER(l1_category) = \'PLUS\' AND UPPER(category) IN (\'TROUSERS\', \'JEANS\') AND size = \'4XL\' THEN 30 WHEN UPPER(l1_category) = \'PLUS\' AND UPPER(category) IN (\'TROUSERS\', \'JEANS\') AND size IN (\'5XL\', \'6XL\') THEN 20 WHEN UPPER(l1_category) = \'PLUS\' AND UPPER(category) IN (\'TROUSERS\', \'JEANS\') AND size IN (\'7XL\', \'8XL\') THEN 10 ELSE NULL END AS required_qty, CASE WHEN v.sku_group IS NULL THEN NULL WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'XS\' THEN 10 WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'S\' THEN 30 WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'M\' THEN 40 WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'L\' THEN 40 WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'XL\' THEN 30 WHEN UPPER(l1_category) IN (\'SNITCH\', \'LUXE\') AND size = \'2XL\' THEN 10 WHEN UPPER(l1_category) = \'PLUS\' AND UPPER(category) IN (\'SHIRTS\', \'TSHIRTS\') AND size IN (\'3XL\', \'4XL\', \'5XL\', \'6XL\') THEN 20 WHEN UPPER(l1_category) = \'PLUS\' AND UPPER(category) IN (\'TROUSERS\', \'JEANS\') AND size = \'3XL\' THEN 30 WHEN UPPER(l1_category) = \'PLUS\' AND UPPER(category) IN (\'TROUSERS\', \'JEANS\') AND size = \'4XL\' THEN 30 WHEN UPPER(l1_category) = \'PLUS\' AND UPPER(category) IN (\'TROUSERS\', \'JEANS\') AND size IN (\'5XL\', \'6XL\') THEN 20 WHEN UPPER(l1_category) = \'PLUS\' AND UPPER(category) IN (\'TROUSERS\', \'JEANS\') AND size IN (\'7XL\', \'8XL\') THEN 10 ELSE NULL END AS offline_required_qty, FROM base b LEFT JOIN variant_exists v USING (sku_group, size) ), online_flag AS ( SELECT date, sku_group, CASE WHEN MAX(CASE WHEN size = \'S\' AND wh_qty > 1 THEN 1 ELSE 0 END) = 1 AND MAX(CASE WHEN size = \'M\' AND wh_qty > 1 THEN 1 ELSE 0 END) = 1 AND MAX(CASE WHEN size = \'L\' AND wh_qty > 1 THEN 1 ELSE 0 END) = 1 THEN \'Full Size Inv\' ELSE \'Not Full Size\' END AS wh_online_remark, CASE when upper(l1_category) like \'LONG%\' THEN \'Full Size Inv\' when upper(l1_category) like \'PLUS%\' THEN CASE WHEN MAX(CASE WHEN size = \'3XL\' AND total_qty > 1 THEN 1 ELSE 0 END) = 1 AND MAX(CASE WHEN size = \'4XL\' AND total_qty > 1 THEN 1 ELSE 0 END) = 1 AND MAX(CASE WHEN size = \'5XL\' AND total_qty > 1 THEN 1 ELSE 0 END) = 1 THEN \'Full Size Inv\' ELSE \'Not Full Size\' END else case WHEN MAX(CASE WHEN size = \'S\' AND total_qty > 1 THEN 1 ELSE 0 END) = 1 AND MAX(CASE WHEN size = \'M\' AND total_qty > 1 THEN 1 ELSE 0 END) = 1 AND MAX(CASE WHEN size = \'L\' AND total_qty > 1 THEN 1 ELSE 0 END) = 1 THEN \'Full Size Inv\' ELSE \'Not Full Size\' END end AS total_online_remark FROM req GROUP BY 1, 2,l1_category ), final_flag AS ( SELECT date, sku_group, CASE WHEN SUM( CASE WHEN required_qty IS NOT NULL AND wh_qty >= required_qty THEN 1 ELSE 0 END ) >= 4 THEN \'Full Size Inv\' ELSE \'Not Full Size\' END AS wh_remark, CASE WHEN MAX( CASE WHEN UPPER(l1_category) like \'LONG%\' THEN 1 ELSE 0 END ) = 1 THEN \'Full Size Inv\' WHEN MAX( CASE WHEN UPPER(l1_category) = \'PLUS\' THEN 1 ELSE 0 END ) = 1 THEN CASE WHEN SUM( CASE WHEN offline_required_qty IS NOT NULL AND store_qty + jit_qty >= offline_required_qty THEN 1 ELSE 0 END ) >= 4 THEN \'Full Size Inv\' ELSE \'Not Full Size\' END ELSE CASE WHEN MAX( CASE WHEN size = \'S\' AND variant_exists = 1 AND store_qty + jit_qty >= 31 THEN 1 ELSE 0 END ) = 1 AND MAX( CASE WHEN size = \'M\' AND variant_exists = 1 AND store_qty + jit_qty >= 41 THEN 1 ELSE 0 END ) = 1 AND MAX( CASE WHEN size = \'L\' AND variant_exists = 1 AND store_qty + jit_qty >= 41 THEN 1 ELSE 0 END ) = 1 AND MAX( CASE WHEN size = \'XL\' AND variant_exists = 1 AND store_qty + jit_qty >= 31 THEN 1 ELSE 0 END ) = 1 AND ( MAX( CASE WHEN size = \'XS\' AND variant_exists = 1 AND store_qty + jit_qty >= 1 THEN 1 ELSE 0 END ) = 1 OR MAX( CASE WHEN size = \'2XL\' AND variant_exists = 1 AND store_qty + jit_qty >= 1 THEN 1 ELSE 0 END ) = 1 OR MAX( CASE WHEN size IN (\'XS\', \'2XL\') AND variant_exists = 1 THEN 1 ELSE 0 END ) = 0 ) THEN \'Full Size Inv\' ELSE \'Not Full Size\' END END AS store_jit_remark, CASE WHEN SUM( CASE WHEN required_qty IS NOT NULL AND total_qty >= required_qty THEN 1 ELSE 0 END ) >= 4 THEN \'Full Size Inv\' ELSE \'Not Full Size\' END AS total_remark FROM req GROUP BY 1, 2 ), qty_totals AS ( SELECT date, sku_group, SUM(wh_qty) AS final_wh_qty, SUM(store_qty) AS final_store_qty, SUM(store_qty + jit_qty) AS final_store_jit_qty, SUM(total_qty) AS final_total_qty FROM req GROUP BY 1, 2 ) , final as (SELECT DISTINCT COALESCE(f.date, q.date) AS date, COALESCE(f.sku_group, q.sku_group) AS sku_group, COALESCE( mm.l1_category, CASE WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'r4mbg%\' THEN \'plus_size\' WHEN UPPER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4MBGSS%\' THEN \'plus_size\' WHEN UPPER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4MBGSR%\' THEN \'plus_size\' WHEN UPPER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4MBGSD%\' THEN \'plus_size\' WHEN UPPER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4MBGST%\' THEN \'plus_size\' WHEN UPPER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4ML%\' THEN \'luxe\' WHEN UPPER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4MTL%\' THEN \'luxe\' WHEN UPPER(COALESCE(f.sku_group, q.sku_group)) LIKE \'SH00%\' THEN \'long_tail\' WHEN UPPER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4MBL%\' THEN \'long_tail\' WHEN UPPER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4MHT%\' THEN \'long_tail\' WHEN UPPER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4MCP%\' THEN \'long_tail\' WHEN UPPER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4MBD%\' THEN \'long_tail\' WHEN UPPER(COALESCE(f.sku_group, q.sku_group)) LIKE \'SN%\' THEN \'long_tail\' WHEN UPPER(COALESCE(f.sku_group, q.sku_group)) LIKE \'SH%\' THEN \'long_tail\' WHEN UPPER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4MSFC%\' THEN \'long_tail\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4lrn%\' THEN \'luxe\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4lpl%\' THEN \'luxe\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4ltr%\' THEN \'luxe\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4lch%\' THEN \'luxe\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4lje%\' THEN \'luxe\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4ljk%\' THEN \'luxe\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4lsw%\' THEN \'luxe\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4lhd%\' THEN \'luxe\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4los%\' THEN \'luxe\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4lsh%\' THEN \'luxe\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4lshs%\' THEN \'luxe\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4lsfs%\' THEN \'luxe\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4lbl%\' THEN \'luxe\' WH