CE(f.sku_group, q.sku_group)) LIKE \'4jk%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4sw%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4hd%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4os%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4sh%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4shs%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4sfs%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4bl%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4ca%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4swt%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4cd%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4jo%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4bx%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4bg%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4br%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4tru%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4sho%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4ac%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4su%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4bt%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4pr%\' THEN \'snitch\' WHEN LOWER(COALESCE(f.sku_group, q.sku_group)) LIKE \'4py%\' THEN \'snitch\' ELSE \'snitch\' END ) AS l1_category, mm.category, mm.meta1, mm.meta2, mm.meta3, mm.cogs, q.final_wh_qty, q.final_store_qty, q.final_store_jit_qty, q.final_total_qty, f.wh_remark, f.store_jit_remark, f.total_remark, o.wh_online_remark, o.total_online_remark, FROM final_flag f FULL OUTER JOIN qty_totals q USING (date, sku_group) LEFT JOIN snitch_db.maplemonk.meta_mapping_cogs_sku mm ON COALESCE(f.sku_group, q.sku_group) = mm.sku_group LEFT JOIN online_flag o ON COALESCE(f.date, q.date) = o.date AND COALESCE(f.sku_group, q.sku_group) = o.sku_group LEFT JOIN ( SELECT DISTINCT date, sku_group, inventory_ageing_bucket FROM snitch_db.maplemonk.category_date_wise_data ) c ON COALESCE(f.date, q.date) = c.date AND COALESCE(f.sku_group, q.sku_group) = c.sku_group ) select date,sku_group,l1_category,category,meta1,meta2,meta3,cogs, final_wh_qty, final_store_qty, final_store_jit_qty, final_total_qty, case when l1_category like \'long%\' then \'Full Size Inv\' else wh_remark end wh_remark, case when l1_category like \'long%\' then \'Full Size Inv\' else store_jit_remark end store_jit_remark, case when l1_category like \'long%\' then \'Full Size Inv\' else total_remark end total_remark, case when l1_category like \'long%\' then \'Full Size Inv\' else wh_online_remark end wh_online_remark, case when l1_category like \'long%\' then \'Full Size Inv\' else total_online_remark end total_online_remark, from final ;",
